def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting algorithm with O(n log n) time.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find position to replace: first element >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

