def solve(tokens):
    """Evaluate Reverse Polish Notation.
    tokens: list of strings containing integers or '+', '-', '*', '/'.
    Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0
